class Solution {
public:
    long long sumK(int n, int k) {
        long long m = n / k;
        return (long long)k * m * (m + 1) / 2;
    }
    int sumOfMultiples(int n) {
        long long total = sumK(n, 3) + sumK(n, 5) + sumK(n, 7)
                        - sumK(n, 15) - sumK(n, 21) - sumK(n, 35)
                        + sumK(n, 105);
        return (int)total;
    }
};
